import test from "node:test";
import assert from "node:assert/strict";
import { plainText, manuscriptStats, countForWriting, characterCount, novelpiaCount } from "../core/text.mjs";
import { normalizeWriting } from "../core/platforms.mjs";

test("노벨피아 공개식: 문장부호, 곡선 따옴표, HTML 이스케이프와 UTF-16", () => {
  // Expected values from the published 2022 editor expression applied to
  // HTML text nodes; deliberately not generated by the implementation.
  const cases = [
    ["가.,!?'\" … < > & 😀", 17],
    ['"안녕..."', 2], ["“안녕……”", 6],
    ["<용사> &", 15], ["😀", 2], ["👨‍👩‍👧‍👦", 11],
    ["가\u200e나", 2], ["가\u200b나", 3],
    ["가\n\t \r나", 2], ["&amp;", 9], ["&lrm;", 9],
  ];
  for (const [text, expected] of cases) assert.equal(novelpiaCount(text), expected, JSON.stringify(text));
  const rules = normalizeWriting({platform: "novelpia"});
  assert.equal(countForWriting(manuscriptStats('**가.,!?\'"** … &lt; &gt; &amp; 😀'), rules), 17);
});

test("마크다운을 본문으로 변환: 엔티티 한 번만 해제, 코드/이스케이프/목록 보존", () => {
  assert.equal(plainText("&hellip; &amp;lt; &#38;amp;"), "… &lt; &amp;");
  assert.equal(plainText("`&amp;` \\*"), "&amp; *");
  assert.equal(plainText("```\n&amp;\n```"), "&amp;");
  assert.equal(plainText("- 가\n- 나"), "가\n나");
  assert.equal(plainText("<p>가<br>나</p><p>다</p>"), "가\n나\n다");
  assert.equal(plainText("![그림 설명](cover.png)"), "");
});

test("이모지 단위: 플랫폼/사용자/기본 수치 모두 UTF-16", () => {
  for (const platform of ["novelpia", "munpia", "naver", "kakao", "custom"]) {
    const rules = normalizeWriting({platform, unit: "codepoint"});
    assert.equal(rules.unit, "utf16");
    assert.equal(countForWriting(manuscriptStats("😀👨‍👩‍👧‍👦"), rules), 13);
  }
  assert.equal(characterCount("😀\n\n👨‍👩‍👧‍👦", true), 13);
});

test("과거 프리셋 자동 교정과 사용자 규칙 보존", () => {
  const p = normalizeWriting({platform: "novelpia", rule:"noSpace", unit:"codepoint", goal:4321});
  assert.equal(p.rule, "novelpia"); assert.equal(p.goal, 4321);
  assert.deepEqual(normalizeWriting(p), p);
  const adjusted = normalizeWriting({platform: "novelpia", rule:"all", unit:"utf16", goal:7000});
  assert.equal(adjusted.platform,"custom"); assert.equal(adjusted.rule,"all"); assert.equal(adjusted.goal,7000);
  const custom = normalizeWriting({platform:"custom", rule:"collapsed", punctuation:"ascii", ellipsisWeight:3, goal:4444});
  assert.equal(countForWriting(manuscriptStats("가  나\n\n…!😀"), custom), 9);
  assert.equal(countForWriting(manuscriptStats("가😀!"), {...custom,excludeSpecial:true}), 1);
});
